function hex(c){return "#"+Object.values(c).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("");}
const out=[];
for(const id of ids){
  const n=await figma.getNodeByIdAsync(id);
  if(!n){out.push({id,missing:true});continue;}
  const o={id,name:n.name,type:n.type,w:Math.round(n.width),h:Math.round(n.height)};
  if(Array.isArray(n.fills)&&n.fills.length){o.root=n.fills[0].type==="SOLID"?hex(n.fills[0].color):n.fills[0].type;}
  const colors=new Set();
  function walk(x){
    if(Array.isArray(x.fills))x.fills.forEach(f=>{if(f.type==="SOLID")colors.add("F"+hex(f.color));else if(f.type==="IMAGE")colors.add("IMG");else colors.add(f.type);});
    if(Array.isArray(x.strokes))x.strokes.forEach(f=>{if(f.type==="SOLID")colors.add("S"+hex(f.color));});
    if("children" in x)x.children.forEach(walk);
  }
  walk(n);
  o.colors=[...colors];
  out.push(o);
}
return JSON.stringify(out);

