const C={brand:{r:0.012,g:0.451,b:0.953},ink:{r:0.125,g:0.055,b:0.196},sub:{r:0.482,g:0.482,b:0.522},muted:{r:0.678,g:0.678,b:0.678},bg:{r:0.969,g:0.973,b:0.984},card:{r:1,g:1,b:1},border:{r:0.925,g:0.929,b:0.945},tint:{r:0.914,g:0.949,b:0.996},white:{r:1,g:1,b:1},star:{r:1,g:0.71,b:0.13},disabled:{r:0.78,g:0.79,b:0.82}};
