async function T(chars,size,style,color,align){const t=figma.createText();t.fontName={family:style==="A"?"Andika":"Poppins",style:style==="M"?"Medium":style==="SB"?"SemiBold":"Regular"};t.characters=chars;t.fontSize=size;t.fills=solid(color);if(align)t.textAlignHorizontal=align;return t;}
async function inst(id){const c=await figma.getNodeByIdAsync(id);if(!c)throw new Error("missing "+id);return c.createInstance();}
function mkScreen(name,x,y,bg){const f=figma.createFrame();f.name=name;f.resize(402,874);f.x=x;f.y=y;f.fills=solid(bg||C.bg);f.clipsContent=true;page.appendChild(f);return f;}
async function shell(screen,white){
 const sb=await inst("1:33");sb.x=0;sb.y=0;screen.appendChild(sb);
 const hi=await inst("1:43");hi.x=0;hi.y=840;screen.appendChild(hi);
 if(white){const walk=(node)=>{if(node.type==="VECTOR"||node.type==="RECTANGLE"||node.type==="ELLIPSE"||node.type==="TEXT"||node.type==="BOOLEAN_OPERATION"||node.type==="LINE"){try{node.fills=solid(C.white);}catch(e){}}if("children" in node)node.children.forEach(walk);};walk(sb);walk(hi);}
}
async function navBack(screen,title,y){
 const nb=await inst("10:8");nb.x=0;nb.y=y||47;screen.appendChild(nb);
 if(title===null)nb.findOne(n=>n.name==="Title").visible=false;
 else if(title)nb.findOne(n=>n.name==="Title").characters=title;
 return nb;
}
async function tabbar(screen,current){
 const tb=await inst("10:26");tb.x=0;tb.y=790;screen.appendChild(tb);
 const items=tb.findAll(n=>n.name==="Item");
 const order=["Home","Wallet","Guide","Chart"];
 items.forEach((it,i)=>{
  const on=order[i]===current;
  const ic=it.findOne(n=>n.type==="INSTANCE");
  const lb=it.findOne(n=>n.type==="TEXT");
  if(ic)ic.fills=solid(on?C.brand:C.muted);
  if(lb)lb.fills=solid(on?C.brand:C.muted);
 });
 return tb;
}
async function button(parent,x,y,w,label,variant){
 if(variant==="default"){const b=await inst("1:25");b.resize(w,50);b.x=x;b.y=y;parent.appendChild(b);const l=b.findOne(n=>n.type==="TEXT");l.fontName={family:"Poppins",style:"SemiBold"};l.characters=label;l.fontSize=14;return b;}
 const b=figma.createFrame();b.resize(w,50);b.cornerRadius=25;b.fills=solid(variant==="tint"?C.tint:C.card);if(variant==="outline"){b.fills=solid(C.card);b.strokes=solid(C.border);b.strokeWeight=1;}b.x=x;b.y=y;b.name=label;parent.appendChild(b);
 const l=await T(label,14,"SB",variant==="tint"?C.brand:C.ink,"CENTER");l.resize(w,21);l.x=0;l.y=15;b.appendChild(l);return b;
}
