const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const frames=page.children.filter(n=>n.type==="FRAME");
const comps=page.children.filter(n=>n.type==="COMPONENT");
let totalReactions=0;
const perFrame=frames.map(f=>{
 let c=0;
 f.findAll(n=>n.reactions&&n.reactions.length>0).forEach(n=>c+=n.reactions.length);
 totalReactions+=c;
 return f.name+" ("+Math.round(f.width)+"x"+Math.round(f.height)+") reactions:"+c;
});
return "PAGE ID: "+page.id+"\nFRAMES: "+frames.length+"\nCOMPONENTS: "+comps.length+"\nTOTAL REACTIONS: "+totalReactions+"\n"+perFrame.join("\n");
